using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CleromancyCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/CleromancyCustomDescription", order = 0)]
public class CleromancyCustomDescription : CustomBattleActionDescription
{
	private const string forEachDieDiscardedID = "ForEachDieDiscarded";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string text = Smart.Format(base.localizationManager.GetLocalizedDiscardDieFromHand(), GetFinalAmountWithoutEquation(amountModified));
		CleromancyAction cleromancyAction = battleAction as CleromancyAction;
		return text + "\n" + Smart.Format(base.localizationManager.GetLocalizedString("ForEachDieDiscarded"), cleromancyAction.LightShieldAction.GetActionDescription(cleromancyAction.AmountOfLightShieldPerDice).RemoveLastIfDotOrComma()) + "\n" + base.localizationManager.GetLocalizedDrawTheSameAmount();
	}
}
